const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // Define NYC geometry
    const nyc = ee.Geometry.Rectangle([-74.3, 40.5, -73.7, 40.9]);

    // Get Landsat 7 data for August 14, 2002
    const collection = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(nyc)
      .filterDate('2002-08-14', '2002-08-15')
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    const size = await collection.size().getInfo();
    console.log(`Images found: ${size}`);

    if (size === 0) {
      // Try wider date range
      const collection2 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterBounds(nyc)
        .filterDate('2002-08-10', '2002-08-20')
        .filter(ee.Filter.lt('CLOUD_COVER', 30));

      const size2 = await collection2.size().getInfo();
      console.log(`Images with wider range: ${size2}`);

      if (size2 === 0) {
        console.log("<answer>C1</answer>");
        return;
      }
    }

    const image = collection.mean();

    // Calculate NDVI
    const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');

    // Calculate surface temperature (Landsat 7 band 6)
    const thermal = image.select('ST_B6').multiply(0.00341802).add(149.0).subtract(273.15).rename('temp');

    // Mask water using NDVI (water typically has NDVI < 0)
    const landMask = ndvi.gt(0);

    // Mask clouds using QA band
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)
      .and(qa.bitwiseAnd(1 << 4).eq(0));

    // Apply masks
    const maskedNDVI = ndvi.updateMask(landMask).updateMask(cloudMask);
    const maskedTemp = thermal.updateMask(landMask).updateMask(cloudMask);

    // Check pixel counts
    const stats = await maskedNDVI.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: nyc,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const pixelCount = stats.NDVI || 0;
    console.log(`Valid pixels: ${pixelCount}`);

    if (pixelCount === 0) {
      console.log("<answer>C2</answer>");
      return;
    }

    // Sample points and calculate correlation
    const combined = maskedNDVI.addBands(maskedTemp);
    const sample = combined.sample({
      region: nyc,
      scale: 3000,
      numPixels: 500,
      geometries: false
    });

    const sampleSize = await sample.size().getInfo();
    console.log(`Sample points: ${sampleSize}`);

    if (sampleSize === 0) {
      console.log("<answer>C2</answer>");
      return;
    }

    // Calculate correlation
    const correlation = await sample.reduceColumns({
      reducer: ee.Reducer.pearsonsCorrelation(),
      selectors: ['NDVI', 'temp']
    }).getInfo();

    const corr = correlation.correlation;
    const pValue = correlation['p-value'];

    console.log(`Correlation: ${corr}`);
    console.log(`P-value: ${pValue}`);

    // Get mean values for context
    const meanStats = await combined.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: nyc,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    console.log(`Mean NDVI: ${meanStats.NDVI ? meanStats.NDVI.toFixed(3) : 'N/A'}`);
    console.log(`Mean Temp: ${meanStats.temp ? meanStats.temp.toFixed(2) : 'N/A'}°C`);

    if (corr === null || isNaN(corr) || meanStats.NDVI === null || meanStats.temp === null) {
      console.log("<answer>C3</answer>");
      return;
    }

    // Negative correlation means temperature decreases with higher vegetation
    if (corr < -0.1 && pValue < 0.1) {
      console.log("<answer>A</answer>");
    } else {
      console.log("<answer>B</answer>");
    }

  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log("<answer>D</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
